sys_script.script:
(function executeRule(
    current,
    previous
) {

    /* ======================================================
       SAFETY
    ====================================================== */

    if (
        !current ||
        !current.isValidRecord()
    ) {

        return;
    }


    var reportType =
        current.getValue(
            'report_type'
        );


    if (!reportType) {

        return;
    }


    /* ======================================================
       WAIT UNTIL AI PROCESSING IS COMPLETE
    ====================================================== */

    if (
        !current.ai_processed
            .changesTo(
                true
            )
    ) {

        return;
    }


    /* ======================================================
       FOUND REPORT:
       REQUEST ON-DEMAND PI LOOKUP WINDOW REFRESH

       Description Similarity
       Image Attribute Similarity
       Unique Feature Similarity

       Lost reports do NOT require this because Lost records
       are used directly as PI prediction/test input.
    ====================================================== */

    if (
        reportType == 'found'
    ) {

        try {

            var refreshManager =
                new CampusMatchPIRefreshManager();


            var refreshResult =
                refreshManager
                    .refreshForFoundItem(
                        current.getUniqueValue()
                    );


            gs.info(
                'CampusMatch: PI refresh requested for Found Item ' +
                current.getUniqueValue() +
                ' | Success=' +
                refreshResult.success +
                ' | Description=' +
                refreshResult.description +
                ' | Image=' +
                refreshResult.image +
                ' | Unique=' +
                refreshResult.unique
            );

        }
        catch (refreshEx) {

            /*
             * Do NOT stop matching completely if the
             * on-demand refresh request fails.
             *
             * The normal 15-minute PI update still exists
             * and pending-match retry can recover later.
             */

            gs.error(
                'CampusMatch: PI refresh request failed for Found Item ' +
                current.getUniqueValue() +
                '. Error: ' +
                refreshEx.message
            );
        }
    }


    /* ======================================================
       INITIAL MATCHING ATTEMPT

       LOST:
       PI can immediately use the Lost record as prediction
       input against Found records already in the lookup
       window.

       FOUND:
       The PI refresh above is asynchronous.

       Therefore this initial attempt may still find that
       the new Found record is not yet available in PI.

       In that case:
       → Pending Match records remain with empty PI scores.
       → Scheduled retry recalculates them after the
         run-once PI refresh finishes.
    ====================================================== */

    try {

        var orchestrator =
            new CampusMatchMatchOrchestrator();


        orchestrator.processItem(
            current
        );


        gs.info(
            'CampusMatch: Initial PI matching attempt completed ' +
            'for ' +
            reportType +
            ' Item ' +
            current.getUniqueValue()
        );

    }
    catch (matchEx) {

        gs.error(
            'CampusMatch: Initial PI matching attempt failed ' +
            'for ' +
            reportType +
            ' Item ' +
            current.getUniqueValue() +
            '. Error: ' +
            matchEx.message
        );
    }


})(
    current,
    previous
);
